const raw = $input.first().json;
const j = (raw && raw.body) ? raw.body : raw;
const val = (j && j.messages) ? j : (j.value || (j.entry && j.entry[0] && j.entry[0].changes && j.entry[0].changes[0] && j.entry[0].changes[0].value) || j);
const messages = (val && val.messages) || [];
if (!messages.length) {
  return [{ json: { is_message: false } }];
}
const m = messages[0];
const contact = ((val.contacts) || [])[0] || {};
const type = m.type || 'unknown';
let text = '';
if (type === 'text') text = (m.text && m.text.body) || '';
else if (type === 'interactive') text = (m.interactive && ((m.interactive.button_reply && m.interactive.button_reply.title) || (m.interactive.list_reply && m.interactive.list_reply.title))) || '';
else if (type === 'button') text = (m.button && m.button.text) || '';
const mediaId = (m[type] && m[type].id) || '';
return [{ json: {
  is_message: true,
  wa_id: m.from || '',
  message_id: m.id || '',
  message_type: type,
  text_body: text,
  media_id: mediaId,
  timestamp: m.timestamp || '',
  profile_name: (contact.profile && contact.profile.name) || '',
  phone_number_id: (val.metadata && val.metadata.phone_number_id) || '',
  raw_payload: JSON.stringify(j).slice(0, 8000),
} }];

return [{ json: {
  message_text: $json.text || '',
  wa_id: $('Parse WhatsApp Event').item.json.wa_id,
} }];

